    $sql = "SELECT COUNT(*) as total FROM general WHERE Certificado = '$Razon' && Caso_osteo = 'CASO CONFIRMADO' && (Tipo_examen = '$Tipo1' || Tipo_examen = '$Tipo2' || Tipo_examen = '$Tipo3' || Tipo_examen = '$Tipo4' || Tipo_examen = '$Tipo5' || Tipo_examen = '$Tipo6' || Tipo_examen = '$Tipo7' || Tipo_examen = '$Tipo8' || Tipo_examen = '$Tipo9'  || Tipo_examen = '$Tipo10'  || Tipo_examen = '$Tipo11' ||  Tipo_examen = '$Tipo12' || Tipo_examen = '$Tipo13' || Tipo_examen = '$Tipo14' || Tipo_examen = '$Tipo15' || Tipo_examen = '$Tipo16' || Tipo_examen = '$Tipo17' || Tipo_examen = '$Tipo18' || Tipo_examen = '$Tipo19' || Tipo_examen = '$Tipo20' || Tipo_examen = '$Tipo21' || Tipo_examen = '$Tipo22')";;     
    $sentencia = $connect->prepare($sql);
    $sentencia->execute();
    $resultadoE_1 = $sentencia->fetch();
    $total_usuariosE_1 = $resultadoE_1['total'];
    
    $sql = "SELECT COUNT(*) as total FROM general WHERE Certificado = '$Razon' && (Caso_osteo = 'CASO SINTOMÁTICO' || Caso_osteo = 'CASO SINTOMATICO') &&  (Tipo_examen = '$Tipo1' || Tipo_examen = '$Tipo2' || Tipo_examen = '$Tipo3' || Tipo_examen = '$Tipo4' || Tipo_examen = '$Tipo5' || Tipo_examen = '$Tipo6' || Tipo_examen = '$Tipo7' || Tipo_examen = '$Tipo8' || Tipo_examen = '$Tipo9'  || Tipo_examen = '$Tipo10'  || Tipo_examen = '$Tipo11' ||  Tipo_examen = '$Tipo12' || Tipo_examen = '$Tipo13' || Tipo_examen = '$Tipo14' || Tipo_examen = '$Tipo15' || Tipo_examen = '$Tipo16' || Tipo_examen = '$Tipo17' || Tipo_examen = '$Tipo18' || Tipo_examen = '$Tipo19' || Tipo_examen = '$Tipo20' || Tipo_examen = '$Tipo21' || Tipo_examen = '$Tipo22')";;         
    $sentencia = $connect->prepare($sql);
    $sentencia->execute();
    $resultadoE_2 = $sentencia->fetch();
    $total_usuariosE_2 = $resultadoE_2['total'];
    
    $sql = "SELECT COUNT(*) as total FROM general WHERE Certificado = '$Razon' && Caso_osteo = 'NO CASO' &&  (Tipo_examen = '$Tipo1' || Tipo_examen = '$Tipo2' || Tipo_examen = '$Tipo3' || Tipo_examen = '$Tipo4' || Tipo_examen = '$Tipo5' || Tipo_examen = '$Tipo6' || Tipo_examen = '$Tipo7' || Tipo_examen = '$Tipo8' || Tipo_examen = '$Tipo9'  || Tipo_examen = '$Tipo10'  || Tipo_examen = '$Tipo11' ||  Tipo_examen = '$Tipo12' || Tipo_examen = '$Tipo13' || Tipo_examen = '$Tipo14' || Tipo_examen = '$Tipo15' || Tipo_examen = '$Tipo16' || Tipo_examen = '$Tipo17' || Tipo_examen = '$Tipo18' || Tipo_examen = '$Tipo19' || Tipo_examen = '$Tipo20' || Tipo_examen = '$Tipo21' || Tipo_examen = '$Tipo22')";;       
    $sentencia = $connect->prepare($sql);
    $sentencia->execute();
    $resultadoE_3 = $sentencia->fetch();
    $total_usuariosE_3 = $resultadoE_3['total'];
    
    $total_usuariosE = $total_usuariosE_1 + $total_usuariosE_2 + $total_usuariosE_3;
    if($total_usuariosE_1 >= 1) {
        $total_usuariosE_1_porcentaje = round((($total_usuariosE_1/$total_usuariosE)*100), 0, PHP_ROUND_HALF_UP);
    } else {
        $total_usuariosE_1_porcentaje = 0;
    }
    if($total_usuariosE_2 >= 1) {
        $total_usuariosE_2_porcentaje = round((($total_usuariosE_2/$total_usuariosE)*100), 0, PHP_ROUND_HALF_UP);
    } else {
        $total_usuariosE_2_porcentaje = 0;
    }
    if($total_usuariosE_3 >= 1) {
        $total_usuariosE_3_porcentaje = round((($total_usuariosE_3/$total_usuariosE)*100), 0, PHP_ROUND_HALF_UP);
    } else {
        $total_usuariosE_3_porcentaje = 0;
    }
    
        $sql = "SELECT 
            TRIM(SUBSTRING_INDEX(SUBSTRING_INDEX(restricciones, ':', -1), '-', 1)) AS tipo_restriccion,
            TRIM(SUBSTRING_INDEX(restricciones, ':', 1)) AS caracteristica,
            COUNT(*) AS total
        FROM general
        WHERE restricciones IS NOT NULL 
          AND restricciones != ''
          AND restricciones LIKE '%:%'
          AND restricciones LIKE '%-%'
        GROUP BY tipo_restriccion, caracteristica
        ORDER BY total DESC";
        $sentencia = $connect->prepare($sql);
        $sentencia->execute();
        $restricciones = $sentencia->fetchAll(PDO::FETCH_ASSOC);
        $totalRestricciones = 0;
        foreach ($restricciones as $r) { 
            $totalRestricciones += $r['total']; 
        }
        foreach ($restricciones as &$r) {
            $r['porcentaje'] = ($totalRestricciones > 0)
                ? round(($r['total'] / $totalRestricciones) * 100, 0, PHP_ROUND_HALF_UP)
                : 0;
        }
        unset($r);
            $dataRestricciones = [];
            foreach ($restricciones as $r) {
                $dataRestricciones[] = [
                    $r['tipo_restriccion'],
                    $r['total'],
                    $r['porcentaje'] . '%',
                    $r['caracteristica']
                ];
            }
            
            
            
        $sql = "SELECT Nombre_apellidos, Saturacion FROM general 
        WHERE Saturacion IS NOT NULL 
          AND Saturacion != ''";
        $sentencia = $connect->prepare($sql);
        $sentencia->execute();
        $usuarios = $sentencia->fetchAll(PDO::FETCH_ASSOC);
        
        $dataSaturacion = [];
        foreach ($usuarios as $u) {
            $spo2 = (int) filter_var($u['Saturacion'], FILTER_SANITIZE_NUMBER_INT);
        
            if ($spo2 >= 95 && $spo2 <= 100) {
                $clasificacion = 'Normal';
                $accion = 'Apto para labores habituales. No requiere restricciones físicas. Monitoreo rutinario según los protocolos de vigilancia epidemiológica de la empresa.';
            } elseif ($spo2 >= 90 && $spo2 <= 94) {
                $clasificacion = 'Hipoxemia leve';
                $accion = 'Acompañamiento y optimización preventiva (Sin restricción inmediata). El trabajador puede continuar sus labores bajo supervisión. Se recomienda verificar el ajuste y estado de su protección respiratoria permanente. Se aconseja promover pausas activas, asegurar la ventilación del área y sugerir una valoración médica preventiva para identificar causas individuales (como fatiga o condiciones respiratorias leves).';
            } elseif ($spo2 >= 75 && $spo2 <= 89) {
                $clasificacion = 'Hipoxemia moderada';
                $accion = 'Incapacidad temporal y atención médica prioritaria. El trabajador debe suspender sus actividades y retirarse del área operativa de forma segura. Se procede a su traslado a un área de descanso ventilada para una evaluación médica inmediata. Si el centro laboral dispone de personal e insumos de salud, se evalúa el suministro de oxigenoterapia.';
            } elseif ($spo2 < 75) {
                $clasificacion = 'Hipoxemia grave';
                $accion = 'Emergencia médica crítica en el centro de trabajo. Activación inmediata del protocolo de emergencias de la empresa y solicitud de ambulancia o soporte vital externo. Paralización inmediata de las labores en áreas contiguas si se sospecha que la causa se debe a un riesgo ambiental agudo (fuga de gases o ambientes deficientes de oxígeno).';
            } else {
                $clasificacion = 'Sin clasificar';
                $accion = 'Valor fuera de rango o no reconocido.';
            }
        
            // ✅ Solo agregar a la tabla si es Hipoxemia moderada o grave
            if ($clasificacion === 'Hipoxemia moderada' || $clasificacion === 'Hipoxemia grave') {
                $dataSaturacion[] = [
                    $u['Nombre_apellidos'],
                    $clasificacion,
                    $accion
                ];
            }
        }
        
        // Contar SI
        $sql = "SELECT COUNT(*) as total FROM general 
                WHERE UPPER(TRIM(psicosensometrico)) = 'SI'";
        $sentencia = $connect->prepare($sql);
        $sentencia->execute();
        $resultado = $sentencia->fetch(PDO::FETCH_ASSOC);
        $total_si = $resultado['total'];
        
        // Contar NO
        $sql = "SELECT COUNT(*) as total FROM general 
                WHERE UPPER(TRIM(psicosensometrico)) = 'NO'";
        $sentencia = $connect->prepare($sql);
        $sentencia->execute();
        $resultado = $sentencia->fetch(PDO::FETCH_ASSOC);
        $total_no = $resultado['total'];
        
        // Total evaluados (SI + NO)
        $total_evaluados = $total_si + $total_no;
        
        // Porcentajes
        $porcentaje_si = ($total_evaluados > 0) 
            ? round(($total_si / $total_evaluados) * 100, 0, PHP_ROUND_HALF_UP) 
            : 0;
        
        $porcentaje_no = ($total_evaluados > 0) 
            ? round(($total_no / $total_evaluados) * 100, 0, PHP_ROUND_HALF_UP) 
            : 0;
            
            
            // Descripción y acción para SI
        $descripcion_si = 'El conductor ha asistido y completado la evaluación psicosensométrica programada. Los resultados específicos de las aptitudes físicas, visuales y motoras se encuentran detallados de forma individual en cada certificado emitido.';
        
        $accion_si = "Continuar con la programación habitual.\n" .
                     "• Seguir el conducto regular según el PESV.\n" .
                     "• Archivar el documento en la carpeta de cada conductor.\n" .
                     "• Mantener el monitoreo continuo y aplicar las pautas preventivas que dicte el Plan Estratégico de Seguridad Vial de la empresa.";
        
        // Descripción y acción para NO
        $descripcion_no = 'El conductor NO ha asistido o no ha completado la evaluación psicosensométrica programada. Se requiere programar una nueva cita y hacer seguimiento individual.';
        
        $accion_no = "Programar reevaluación psicosensométrica.\n" .
                     "• Notificar al conductor y a su supervisor inmediato.\n" .
                     "• Registrar el caso en el PESV como pendiente.\n" .
                     "• Hacer seguimiento hasta completar la evaluación.";
        
        // Array final con las dos filas
        $dataPsico = [
            [
                'Realizado-Si',
                (int)$total_si,
                $porcentaje_si . '%',
                $descripcion_si,
                $accion_si
            ],
            [
                'Realizado-No',
                (int)$total_no,
                $porcentaje_no . '%',
                $descripcion_no,
                $accion_no
            ]
        ];
            
        $sql = "SELECT 
            Nombre_apellidos,
            TRIM(SUBSTRING_INDEX(SUBSTRING_INDEX(restricciones, ':', -1), '-', 1)) AS restriccion,
            TRIM(SUBSTRING_INDEX(restricciones, ':', 1)) AS caracteristico
                FROM general
                WHERE restricciones IS NOT NULL 
                  AND restricciones != ''
                  AND restricciones LIKE '%:%'
                  AND restricciones LIKE '%-%'
                ORDER BY Nombre_apellidos ASC";
        
        $sentencia = $connect->prepare($sql);
        $sentencia->execute();
        $restriccionesUsuarios = $sentencia->fetchAll(PDO::FETCH_ASSOC);
        $dataRestriccionesUsuarios = [];
        foreach ($restriccionesUsuarios as $r) {
            $dataRestriccionesUsuarios[] = [
                $r['Nombre_apellidos'],
                $r['restriccion'],
                $r['caracteristico']
            ];
        }
?>
