// SOLUCIÓN OPTIMIZADA: Una sola consulta SQL
$sql = "SELECT Cargo, COUNT(*) as total 
        FROM general 
        WHERE Certificado = '$Razon' 
        AND (Tipo_examen = '$Tipo1' || Tipo_examen = '$Tipo2' || Tipo_examen = '$Tipo3' || 
             Tipo_examen = '$Tipo4' || Tipo_examen = '$Tipo5' || Tipo_examen = '$Tipo6' || 
             Tipo_examen = '$Tipo7' || Tipo_examen = '$Tipo8' || Tipo_examen = '$Tipo9' || 
             Tipo_examen = '$Tipo10' || Tipo_examen = '$Tipo11' || Tipo_examen = '$Tipo12' || 
             Tipo_examen = '$Tipo13' || Tipo_examen = '$Tipo14' || Tipo_examen = '$Tipo15' || 
             Tipo_examen = '$Tipo16' || Tipo_examen = '$Tipo17' || Tipo_examen = '$Tipo18' || 
             Tipo_examen = '$Tipo19' || Tipo_examen = '$Tipo20' || Tipo_examen = '$Tipo21' || 
             Tipo_examen = '$Tipo22')
        GROUP BY Cargo 
        ORDER BY total DESC 
        LIMIT 3";

$resultado = $mysqli->query($sql);

// Obtener total general
$sql_total = "SELECT COUNT(*) as total FROM general 
              WHERE Certificado = '$Razon' 
              AND (Tipo_examen = '$Tipo1' || Tipo_examen = '$Tipo2' || Tipo_examen = '$Tipo3' || 
                   Tipo_examen = '$Tipo4' || Tipo_examen = '$Tipo5' || Tipo_examen = '$Tipo6' || 
                   Tipo_examen = '$Tipo7' || Tipo_examen = '$Tipo8' || Tipo_examen = '$Tipo9' || 
                   Tipo_examen = '$Tipo10' || Tipo_examen = '$Tipo11' || Tipo_examen = '$Tipo12' || 
                   Tipo_examen = '$Tipo13' || Tipo_examen = '$Tipo14' || Tipo_examen = '$Tipo15' || 
                   Tipo_examen = '$Tipo16' || Tipo_examen = '$Tipo17' || Tipo_examen = '$Tipo18' || 
                   Tipo_examen = '$Tipo19' || Tipo_examen = '$Tipo20' || Tipo_examen = '$Tipo21' || 
                   Tipo_examen = '$Tipo22')";

$sentencia_total = $connect->prepare($sql_total);
$sentencia_total->execute();
$resultado_total = $sentencia_total->fetch();
$total_usuarios17 = $resultado_total['total'];

// Array para almacenar los tres cargos
$cargos_conclusion = array();

// Procesar resultados y llenar el array
while($row = mysqli_fetch_array($resultado)) { 
    $Cargo = $row['Cargo'];
    $total_usuarios15 = $row['total'];
    
    // Calcular porcentaje
    $total_usuarios15_porcentaje = round((($total_usuarios15/$total_usuarios17)*100), 1, PHP_ROUND_HALF_UP);
    
    // Almacenar para la conclusión general
    $cargos_conclusion[] = array(
        'cargo' => $Cargo,
        'porcentaje' => $total_usuarios15_porcentaje,
        'total' => $total_usuarios15
    );
}

// Ahora sí contar el número de cargos (después de llenar el array)
$num_cargos = count($cargos_conclusion);

// Redacción adaptada según número de cargos
if ($num_cargos == 0) {
    echo "No se encontraron cargos registrados para los criterios especificados.";
} else {
    echo "<h3>Conclusión - Cargos Más Relevantes</h3>";
    
    if ($num_cargos == 1) {
        $c = $cargos_conclusion[0];
        $Cargos = "La totalidad de los trabajadores ({$c['porcentaje']}%) corresponde al cargo de {$c['cargo']} ({$c['total']} empleados).";
        
    } elseif ($num_cargos == 2) {
        $c1 = $cargos_conclusion[0];
        $c2 = $cargos_conclusion[1];
        $suma = $c1['porcentaje'] + $c2['porcentaje'];
        $Cargos = "Los cargos predominantes son: {$c1['cargo']} ({$c1['porcentaje']}%, {$c1['total']} empleados) y "
            . "{$c2['cargo']} ({$c2['porcentaje']}%, {$c2['total']} empleados), "
            . "sumando el " . round($suma, 1) . "% del personal.";
            
    } elseif ($num_cargos == 3) {
        $c1 = $cargos_conclusion[0];
        $c2 = $cargos_conclusion[1];
        $c3 = $cargos_conclusion[2];
        $suma = $c1['porcentaje'] + $c2['porcentaje'] + $c3['porcentaje'];
        $Cargos = "Los tres cargos más relevantes son: {$c1['cargo']} ({$c1['porcentaje']}%), "
            . "{$c2['cargo']} ({$c2['porcentaje']}%) y "
            . "{$c3['cargo']} ({$c3['porcentaje']}%), "
            . "que en conjunto representan el " . round($suma, 1) . "% de la fuerza laboral "
            . "({$c1['total']}, {$c2['total']} y {$c3['total']} empleados respectivamente).";
    }
}
?>

