                    doc.setFontType("bold");
                    doc.text(82, 270, "Resumen de la Importancia                                                                                                                                                                                                                                                            ", {maxWidth: 445,align:'justify', lineHeightFactor: 1.5});
                    doc.setFontType("normal");
                    doc.text(82, 300, "Estas normas técnicas son esenciales porque:                                                                                                                                                                                                                                                               ", {maxWidth: 445,align:'justify', lineHeightFactor: 1.5});
                    var img = new Image()
                    img.src = '../imagine/menos.png'
                    doc.addImage(img, 'png', 82, 325, 6, 3);
                    doc.text(92,330, "Operacionalizan la Ley: Traducen los lineamientos generales del Decreto 1072 en procedimientos y requisitos medibles (ej., ¿cómo se mide el riesgo?, ¿qué examen debe hacerse?).                                                                                                                                                                                                                                                                                        ", {maxWidth: 445,align:'left', lineHeightFactor: 1.5});
                    var img = new Image()
                    img.src = '../imagine/menos.png'
                    doc.addImage(img, 'png', 82, 385, 6, 3);
                    doc.text(92,390, "Garantizan la Calidad: Aseguran que las intervenciones y los ambientes de trabajo cumplan con estándares de calidad y sanidad que protegen directamente la salud del trabajador.                                                                                                                                                                                                                                                                                        ", {maxWidth: 445,align:'left', lineHeightFactor: 1.5});
                    var img = new Image()
                    img.src = '../imagine/menos.png'
                    doc.addImage(img, 'png', 82, 435, 6, 3);
                    doc.text(92,440, "Definen la Vigilancia: Establecen el protocolo de tamizaje y seguimiento clínico, siendo la base para los Programas de Vigilancia Epidemiológica (PVE).                                                                                                                                                                                                                                                                                     ", {maxWidth: 445,align:'left', lineHeightFactor: 1.5});
                    
                    doc.addPage();
                    
                    doc.setFont("times");
                    doc.setFontSize(12);
                    doc.setTextColor(0,0,0);
                    doc.setFontType("bold");
                    doc.myText('4. MARCO LEGAL',{align: "center"},0,100);
                    doc.text(82, 130, "Marco Legal del Sistema de Gestión de Seguridad y Salud en el Trabajo (SG-SST)                                                                                                                                                                                                                                                                                                                                       ", {maxWidth: 445,align:'justify', lineHeightFactor: 1.5});
                    doc.text(82, 160, "4.1. Fundamento Constitucional y Leyes Marco                                                                                                                                                                                                                                                                                                                                           ", {maxWidth: 445,align:'justify', lineHeightFactor: 1.5});
