                    doc.setFontType("bold");
                    doc.text(82, 100, "3.4. Normas de Habilitación y Calidad (Sector Salud)                                                                                                                                                                                                                                                                ", {maxWidth: 445,align:'justify', lineHeightFactor: 1.5});
                    doc.setFontType("normal");
                    var img = new Image()
                    img.src = '../imagine/menos.png'
                    doc.addImage(img, 'png', 82, 125, 6, 3);
                    doc.text(92,130, "Resolución 3100 de 2019: Define los procedimientos y condiciones de habilitación que deben cumplir los Prestadores de Servicios de Salud (como las IPS), incluyendo requisitos de infraestructura y dotación que impactan directamente en la seguridad del paciente y del personal.                                                                                                                                                                                                                                                                                            ", {maxWidth: 445,align:'left', lineHeightFactor: 1.5});
                    var img = new Image()
                    img.src = '../imagine/menos.png'
                    doc.addImage(img, 'png', 82, 205, 6, 3);
                    doc.text(92,210, "Resolución 1401 de 2007: Regula la investigación de incidentes y accidentes de trabajo, estableciendo los lineamientos para el informe y análisis de causalidad.                                                                                                                                                                                                                                                                                           ", {maxWidth: 445,align:'left', lineHeightFactor: 1.5});
                    doc.setFontType("bold");
                    doc.text(82, 270, "Resumen de la Importancia                                                                                                                                                                                                                                                            ", {maxWidth: 445,align:'justify', lineHeightFactor: 1.5});
                    doc.setFontType("normal");
                    doc.text(82, 300, "Estas normas técnicas son esenciales porque:                                                                                                                                                                                                                                                               ", {maxWidth: 445,align:'justify', lineHeightFactor: 1.5});
                    var img = new Image()
                    img.src = '../imagine/menos.png'
                    doc.addImage(img, 'png', 82, 325, 6, 3);
                    doc.text(92,330, "Operacionalizan la Ley: Traducen los lineamientos generales del Decreto 1072 en procedimientos y requisitos medibles (ej., ¿cómo se mide el riesgo?, ¿qué examen debe hacerse?).                                                                                                                                                                                                                                                                                        ", {maxWidth: 445,align:'left', lineHeightFactor: 1.5});
                    var img = new Image()
                    img.src = '../imagine/menos.png'
                    doc.addImage(img, 'png', 82, 385, 6, 3);
                    doc.text(92,390, "Garantizan la Calidad: Aseguran que las intervenciones y los ambientes de trabajo cumplan con estándares de calidad y sanidad que protegen directamente la salud del trabajador.                                                                                                                                                                                                                                                                                        ", {maxWidth: 445,align:'left', lineHeightFactor: 1.5});
                    var img = new Image()
                    img.src = '../imagine/menos.png'
                    doc.addImage(img, 'png', 82, 435, 6, 3);
                    doc.text(92,440, "Definen la Vigilancia: Establecen el protocolo de tamizaje y seguimiento clínico, siendo la base para los Programas de Vigilancia Epidemiológica (PVE).                                                                                                                                                                                                                                                                                     ", {maxWidth: 445,align:'left', lineHeightFactor: 1.5});
                    
                    doc.addPage();
                    
                    doc.setFont("times");
                    doc.setFontSize(12);
                    doc.setTextColor(0,0,0);
                    doc.setFontType("bold");
                    doc.myText('4. MARCO LEGAL',{align: "center"},0,100);
                    doc.text(82, 130, "Marco Legal del Sistema de Gestión de Seguridad y Salud en el Trabajo (SG-SST)                                                                                                                                                                                                                                                                                                                                       ", {maxWidth: 445,align:'justify', lineHeightFactor: 1.5});
                    doc.text(82, 160, "4.1. Fundamento Constitucional y Leyes Marco                                                                                                                                                                                                                                                                                                                                           ", {maxWidth: 445,align:'justify', lineHeightFactor: 1.5});
                    var columns = ['Norma','Objeto Principal y Relevancia en SST'];
                    var data = [['Constitución Política de Colombia (1991)','Constitución Política de Colombia (1991). Artículo 25: Establece el trabajo como un derecho y una obligación social, garantizando que se desarrolle en condiciones dignas y justas. Artículo 49: Garantiza a todas las personas la atención en salud, promoviendo la conservación de la salud.'],
                    ['Ley 9 de 1979 (Código Sanitario Nacional)','Primera normativa exhaustiva. Establece las normas para la conservación de la salud individual y colectiva y contiene disposiciones sobre la Salud Ocupacional (Título III).'],
                    ['Ley 100 de 1993. Crea el Sistema de Seguridad Social Integral en Colombia, incluyendo el Sistema General de Riesgos Profesionales (hoy Laborales).','Ley 100 de 1993	Crea el Sistema de Seguridad Social Integral en Colombia, incluyendo el Sistema General de Riesgos Profesionales (hoy Laborales).'],
                    ['Ley 1562 de 2012','Modifica el Sistema de Riesgos Laborales, define la Salud Ocupacional como Seguridad y Salud en el Trabajo (SST) y establece el alcance del SG-SST para todos los empleadores.']];
                    doc.autoTable(columns,data, {margin:{ top: 180 , left: 90 },  
                    styles: {font: 'times', fontStyle:'bold', fontSize:10, overflow: 'linebreak', overflowColumns: 'linebreak', halign: 'center', valign:'middle', textColor:[255,255,255], lineWidth:0.5, lineColor:[79, 84, 99], fillColor: [79, 84, 99]}, 
                    columnStyles: {0:{columnWidth: 150, fontStyle:'bold'},1: {columnWidth:300,fontStyle:'bold'}},                                                                                                                                                                                                                                            
                    bodyStyles:{textColor:[0,0,0], fontSize:10, font: 'times', fontStyle:'normal', halign: 'left', lineColor:[0,0,0], lineWidth:0.5, fillColor:false}});
                    doc.text(82, 450, "4.2. Decretos Regulatorios (El Pilar del Sistema)                                                                                                                                                                                                                                                                                                                                          ", {maxWidth: 445,align:'justify', lineHeightFactor: 1.5});
                    var columns = ['Norma','Objeto Principal y Relevancia en SST'];
                    var data = [['Decreto 1072 de 2015','Decreto Único Reglamentario del Sector Trabajo. Consolida y regula la implementación, el mantenimiento y la mejora continua del SG-SST para todos los empleadores públicos y privados (Libro 2, Parte 2, Título 4, Capítulo 6). Es la norma marco actual.'],
                    ['Decreto Ley 1295 de 1994','Determina la organización y administración del Sistema General de Riesgos Laborales.']];
