                    bodyStyles:{textColor:[0,0,0], fontSize:10, font: 'times', fontStyle:'normal', halign: 'left', lineColor:[0,0,0], lineWidth:0.5, fillColor:false}});
                    
                    
                    doc.addPage();
                    
