                    doc.setFontType("bold");
                    doc.myText('5. METODOLOGÍA',{align: "center"},0,100);
                    doc.setFontSize(11);
                    doc.setFontType("normal");
                    doc.text(82,130, "La metodología empleada para el análisis de las condiciones de salud se fundamenta en un enfoque epidemiológico y sistémico, diseñado para convertir los hallazgos clínicos de las evaluaciones ocupacionales periódicas en información estratégica para la gestión del sg-sst de <?php echo $Razon ?> la población objeto de estudio fue de <?php echo $Total ?> trabajadores.                                                                                                                                                                                                                                                               ", {maxWidth: 445,align:'justify', lineHeightFactor: 1.5});
                    doc.setFontType("bold");
                    doc.setTextColor(0, 0, 0);
                    doc.text(82,220, "5.1. RECOLECCIÓN Y CONSOLIDACIÓN DE DATOS (FASE DE ENTRADA)                                                                                                                                                                                                                                                              ", {maxWidth: 445,align:'justify', lineHeightFactor: 1.5});
                    doc.setFontType("normal");
                    doc.text(82,250, "Esta fase se enfoca en asegurar la calidad y exhaustividad de los datos primarios para un análisis robusto.                                                                                                                                                                                                                                                              ", {maxWidth: 445,align:'justify', lineHeightFactor: 1.5});
                    var img = new Image()
                    img.src = '../imagine/menos.png'
                    doc.addImage(img, 'png', 82, 285, 6, 3);
                    doc.text(92,290, "FUENTE DE DATOS PRIMARIOS: se extrajeron los datos clave de cada expediente médico ocupacional, incluyendo:                                                                                                                                                                                                                                                                                    ", {maxWidth: 445,align:'left', lineHeightFactor: 1.5});
                    doc.text(102,340, "• Diagnósticos médicos (codificados bajo cie-10).                                                                                                                                                                                                                                                                                    ", {maxWidth: 445,align:'left', lineHeightFactor: 1.5});
                    doc.text(102,360, "• Hallazgos del examen físico (fuerza, rango de movimiento, dolor).                                                                                                                                                                                                                                                                                    ", {maxWidth: 445,align:'left', lineHeightFactor: 1.5});
                    doc.text(102,380, "• Antecedentes laborales y factores de riesgo individuales (imc, hábitos).                                                                                                                                                                                                                                                                                    ", {maxWidth: 445,align:'left', lineHeightFactor: 1.5});
                    doc.text(102,400, "• Exámenes complementarios: audiometrías, visiometrías, y demás que apliquen.                                                                                                                                                                                                                                                                                    ", {maxWidth: 445,align:'left', lineHeightFactor: 1.5});
                    var img = new Image()
                    img.src = '../imagine/menos.png'
                    doc.addImage(img, 'png', 82, 435, 6, 3);
                    doc.text(92,430, "INTEGRACIÓN CON SST: los datos de salud se consolidaron con la matriz de peligros y riesgos de la empresa para establecer la relación entre la condición de salud y la exposición ocupacional para las evaluaciones se tuvo en cuenta el perfil profesiografico para cada cargo reportado por la empresa en cumplimiento normativo.                                                                                                                                                                                                                                                                                 ", {maxWidth: 445,align:'left', lineHeightFactor: 1.5});
                    var img = new Image()
