                    doc.text(82, 100, "3.4. Normas de Habilitación y Calidad (Sector Salud)                                                                                                                                                                                                                                                                ", {maxWidth: 445,align:'justify', lineHeightFactor: 1.5});
                    doc.setFontType("normal");
                    var img = new Image()
