        $(document).ready(function() {
            Boton();
            function Boton() {
                 $.ajax({
                    type: "post",
                    url: "../sobreescritura.php",
                    data: "reescribir=" + 0,
                    success: function(response) {
                        const tasks = JSON.parse(response);
                        let template = '';
                        tasks.forEach(task => {
                            template += `${task.Sobrescritura}`
                        });
                        if(template == 1) {
                            document.getElementById("sobrescritura").style.border = "1px solid #e7744f";
                        } else {
                             document.getElementById("sobrescritura").style.border = "1px solid #999999";
                        }
                    }
                });
            }
            $(document).on('click', '#sobrescritura', (e) => {
                $.ajax({
                    type: "post",
                    url: "../sobreescritura.php",
                    data: "reescribir=" + 1,
                    success: function(response) {
                        const tasks = JSON.parse(response);
                        let template = '';
                        tasks.forEach(task => {
                            template += `${task.Sobrescritura}`
                        });
                        if(template == 1) {
                            document.getElementById("sobrescritura").style.border = "1px solid #e7744f";
                        } else {
                             document.getElementById("sobrescritura").style.border = "1px solid #999999";
                        }
                    }
                });
            }); 
        });
</script>
</body>
</html>